#[test]
fn the_gantt_html_draws_one_bar_per_dated_task_and_marks_chain_and_statuses() {
    // The fixture: four tasks, design-architecture done and off the chart —
    // three bars. The chain (plan-out-the-tasks → implement-services) wears
    // the red stroke; implement-tests is blocked and takes the orange fill.
    // The card's fields ride on the bar's data attributes.
    let plan = load(PLAN).expect("parses");
    let artifact = schedule(&plan).expect("schedules");
    let html = render::gantt_html(&plan, &artifact);
    assert_eq!(html.matches("class=\"bar ").count(), 3, "{html}");
    assert!(!html.contains("design-architecture"), "{html}");
    assert!(
        html.contains("class=\"bar todo crit\" data-id=\"plan-out-the-tasks\""),
        "{html}"
    );
    assert!(
        html.contains("class=\"bar todo crit\" data-id=\"implement-services\""),
        "{html}"
    );
    assert!(
        html.contains("class=\"bar blocked\" data-id=\"implement-tests\""),
        "{html}"
    );
    assert!(
        html.contains(
            "data-id=\"implement-services\" data-status=\"todo\" \
             data-executor=\"anton\" data-start=\"2026-11-12\" \
             data-end=\"2026-11-18\" data-active-days=\"5\" data-role=\"dev\" \
             data-estimate=\"40\" data-crit=\"1\""
        ),
        "{html}"
    );
    // In-progress takes the blue fill; this one-task plan's chain is the
    // task itself, so the crit stroke composes over it — crit wins on the
    // stroke, the status keeps the fill. The legend lines stand too.
    let yaml = "
unit: person-hours
start: 2026-11-02
roles:
  dev: implements
tasks:
  build: { role: dev, estimate: 8, status: in-progress }
executors:
  anton: { roles: [dev] }
";
    let plan = load(yaml).expect("parses");
    let html = render::gantt_html(&plan, &schedule(&plan).expect("schedules"));
    assert!(
        html.contains("class=\"bar in-progress crit\" data-id=\"build\""),
        "{html}"
    );
    assert!(html.contains("<div>blue: in-progress</div>"), "{html}");
    assert!(html.contains("<div>red stroke: critical path</div>"), "{html}");
}

#[test]
fn a_plan_with_everything_done_still_renders_a_valid_empty_gantt_html() {
    // The all-done artifact carries no dates at all (the autodecision): the
    // window collapses to its single first day, the frame renders — the
    // axis, no bars, no bands.
    let yaml = "
unit: person-hours
start: 2026-11-02
deadline: 2026-11-30
roles:
  dev: implements
tasks:
  seed: { status: done, role: dev }
executors:
  anton: { roles: [dev] }
";
    let plan = load(yaml).expect("parses");
    let artifact = schedule(&plan).expect("schedules");
    assert!(artifact.plan_end.is_none());
    let html = render::gantt_html(&plan, &artifact);
    assert!(html.contains("<title>schedule gantt</title>"), "{html}");
    assert!(html.contains("data-days=\"1\""), "{html}");
    assert!(html.contains("data-start=\"2026-11-02\""), "{html}");
    assert!(html.contains("2026-11"), "{html}");
    assert!(!html.contains("class=\"bar "), "{html}");
    assert!(!html.contains("class=\"band\""), "{html}");
}
